INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('fa65d1eb-44e8-5395-b377-29ff70344073'::uuid, 'c74cf879-1c73-5d55-8afe-0dc2845a66df'::uuid, 'Coverage areas', 'Safi', '["https://lechantier.ma/uploads/media/ec5486582789.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ec5486582789.webp', 'Safi', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d24ac550-7834-508d-a649-eb3b2ed8dcec'::uuid, '1f16a1f0-c1a1-5aa2-a347-b733b67dd75b'::uuid, 'Villa LL', 'Villa à l’architecture épurée, elle marie enduit blanc lin et bois noble pour une ambiance chaleureuse et élégante. Les brise-soleil en bois ipé filtrent la lumière avec finesse. Ouverte sur la nature, avec une piscine centrale, elle incarne un art de vivre sobre, raffiné et intemporel.', '["https://lechantier.ma/uploads/media/31424901077d.webp", "https://lechantier.ma/uploads/media/b604f4e987d0.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/31424901077d.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('66685627-d1cd-5eae-af25-a2745611ed92'::uuid, '1f16a1f0-c1a1-5aa2-a347-b733b67dd75b'::uuid, 'Immeuble R+7', 'Plateau bureaux à l’architecture contemporaine, il se distingue par une façade rythmée et lumineuse. Les encadrements vert amande dynamisent les volumes, tandis que les larges ouvertures assurent un confort visuel optimal. Un projet alliant esthétisme, fonctionnalité et intégration urbaine soignée.', '["https://lechantier.ma/uploads/media/a043eb822d54.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/a043eb822d54.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
