INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('37f9c0be-3d35-5016-8945-7f6f853e93ec'::uuid, '835bc701-c42f-54f6-ab2c-8f20f4af8fec'::uuid, 'Direction régionale et de la délégation', 'Une architecture contextuelle et bioclimatique, qui puise ses fondements dans l’architecture locale — celle du riad marocain — et qui, par son intelligence, fédère l’ensemble des entités du programme. Grâce à sa double peau, le projet évoque le moucharabieh à travers son enveloppe, générant des ambiances singulières, distinctes de celles créées par', '["https://lechantier.ma/uploads/media/44b0ab8d240b.webp", "https://lechantier.ma/uploads/media/76c24284f9c5.webp", "https://lechantier.ma/uploads/media/10f9e145c5c6.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/44b0ab8d240b.webp', 'Oujda', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('1bd914cf-94f6-58ac-b2ed-81526fb61161'::uuid, '835bc701-c42f-54f6-ab2c-8f20f4af8fec'::uuid, 'Réalisation — ARCHITECTE Jaouad FASLA', 'ANGLE BD MED V ET BD EZZEKTOUNI, IMM ATW , 3EME ETAGE, OUJDA', '["https://lechantier.ma/uploads/media/76c24284f9c5.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/76c24284f9c5.webp', 'Oujda', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('90c7adc2-37cd-5b28-a72a-02028a33ad2c'::uuid, '835bc701-c42f-54f6-ab2c-8f20f4af8fec'::uuid, 'Réalisation — ARCHITECTE Jaouad FASLA', NULL, '["https://lechantier.ma/uploads/media/10f9e145c5c6.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/10f9e145c5c6.webp', 'Oujda', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e30ab911-a680-5525-9023-7a93015b7cfa'::uuid, '66e49108-18ef-5760-972b-11e06a309dfb'::uuid, 'Villa KM2 Tanger', 'Une villa de luxe qui se distingue par une esthétique minimaliste et raffinée. Sa façade blanche immaculée, ponctuée de lignes épurées et de volumes simples, exprime élégance et modernité. Chaque détail, des matériaux nobles aux finitions soignées, a été pensé pour créer une harmonie subtile entre sobriété et confort.', '["https://lechantier.ma/uploads/media/2728e447c2d7.webp", "https://lechantier.ma/uploads/media/4283f76f6055.webp", "https://lechantier.ma/uploads/media/b4fa0c68d916.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/2728e447c2d7.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('7364f701-9f15-5a0f-b77a-0747797da77d'::uuid, '66e49108-18ef-5760-972b-11e06a309dfb'::uuid, 'Villa M', 'Cette villa compacte allie modernité et raffinement. Pensée pour optimiser chaque mètre carré, elle offre des espaces lumineux et ouverts malgré sa taille réduite. L’architecture joue sur des volumes simples et des matériaux nobles, créant une atmosphère intime, élégante et contemporaine.', '["https://lechantier.ma/uploads/media/698b5e5bd767.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/698b5e5bd767.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('550c772d-ddb3-5e5a-a96f-0dedfbdfa8af'::uuid, '66e49108-18ef-5760-972b-11e06a309dfb'::uuid, 'Réalisation — Bass studio', NULL, '["https://lechantier.ma/uploads/media/4283f76f6055.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/4283f76f6055.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6d9ec097-c22d-577c-874a-f7a0d7da3617'::uuid, '66e49108-18ef-5760-972b-11e06a309dfb'::uuid, 'Réalisation — Bass studio', NULL, '["https://lechantier.ma/uploads/media/b4fa0c68d916.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/b4fa0c68d916.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('85be9013-8ea0-5e16-beb4-d83046ef14db'::uuid, 'c9916130-7d23-5f51-86b7-5795a567ee68'::uuid, 'Bureau Expert Comptable', 'Aménagement de bureaux pour un cabinet d’expertise comptable, avec création de cloisons vitrées pour des espaces lumineux et fonctionnels. Optimisation de l’organisation des lieux et installation de menuiseries sur mesure, alliant confort et praticité pour répondre aux besoins professionnels.', '["https://lechantier.ma/uploads/media/374325e847c5.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/374325e847c5.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('618a301f-bb3b-569b-8ace-d8d197d282b5'::uuid, 'c9916130-7d23-5f51-86b7-5795a567ee68'::uuid, 'Immeuble plateaux bureaux', 'Construction neuve d’un immeuble de bureaux en R+5, avec suivi complet du chantier. Ce projet allie modernité, fonctionnalité et durabilité pour répondre aux besoins des entreprises. Les plateaux sont conçus pour être modulables, offrant une flexibilité optimale dans l’aménagement des espaces de travail.', '["https://lechantier.ma/uploads/media/ea2509c4d37f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ea2509c4d37f.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('49254cd6-a353-55ab-92e5-c2cb833f55d8'::uuid, '1a974860-2675-5dfa-a5db-ff8dd0156036'::uuid, 'Siège T2S', 'Aménagements du siège de la société T2S', '["https://lechantier.ma/uploads/media/4bc5d1506f95.webp", "https://lechantier.ma/uploads/media/92f5f90e097b.webp", "https://lechantier.ma/uploads/media/15c7cdb611fd.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/4bc5d1506f95.webp', 'Mi Vida', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
