INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6ba1bb31-3c21-57db-b301-738280021d83'::uuid, '0e2ebd8e-fc45-58f4-accc-2eefc94c3ed9'::uuid, 'CONSTRUCTION D’UN IMMEUBLE EN R+5 AVEC R', 'L’approche conceptuelle repose sur une lecture attentive du site et de ses contraintes : orientation, morphologie du tissu urbain, et interaction avec l’espace public. Le volume bâti est traité avec une écriture architecturale contemporaine, jouant sur l’équilibre entre linéarité et verticalité, avec l’utilisation de matériaux sobres (verre, béton', '["https://lechantier.ma/uploads/media/e98aa9f5eff3.webp", "https://lechantier.ma/uploads/media/6c54371985b2.webp", "https://lechantier.ma/uploads/media/97ba04367a97.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/e98aa9f5eff3.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5bef1322-3d20-555d-8609-42ec5e3ab1ae'::uuid, '0e2ebd8e-fc45-58f4-accc-2eefc94c3ed9'::uuid, 'Réalisation — CABINET D''ARCHITECTE MAZOUZ', 'Bureau n°11 3ème étage Imm Ranino AL Massira lot : 1896', '["https://lechantier.ma/uploads/media/6c54371985b2.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/6c54371985b2.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
