INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('12ff74ab-57d4-5371-886a-6038d3d6239d'::uuid, '7964419c-bdd4-5aae-a544-1ca00a062d7f'::uuid, 'Operation Riad Andalous secteur 1 et 2', 'Opération Riad Andalouse – Secteurs 1 et 2 Située à Ville Ibnou Battota, Tanger, l’Opération Riad Andalouse comprend 1 500 logements répartis sur les secteurs 1 et 2. Le projet est conçu pour offrir un cadre de vie moderne, fonctionnel et harmonieux, avec des logements optimisés pour le confort, la luminosité et l’espace.', '["https://lechantier.ma/uploads/media/284ab51e1a6f.webp", "https://lechantier.ma/uploads/media/215213afeb16.webp", "https://lechantier.ma/uploads/media/11b6f4650319.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/284ab51e1a6f.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('90ce1ecb-2788-5422-af8a-ec5fec757ee2'::uuid, '7964419c-bdd4-5aae-a544-1ca00a062d7f'::uuid, 'Usine R+3 a Had soualem', 'Unité de stockage de matériaux de sécurité incendie – Had Soualem Située à Had Soualem, cette unité est dédiée au stockage sécurisé de matériaux de sécurité incendie. Conçue pour allier sécurité, accessibilité et fonctionnalité, elle répond aux normes strictes de stockage et de prévention des risques. L’aménagement intérieur et extérieur garantit', '["https://lechantier.ma/uploads/media/d54d0377f058.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/d54d0377f058.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('8e7f885a-972b-5b72-bc2c-b67bcdda7b2e'::uuid, '7964419c-bdd4-5aae-a544-1ca00a062d7f'::uuid, 'Réalisation — ALT ARCHITECTES', NULL, '["https://lechantier.ma/uploads/media/215213afeb16.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/215213afeb16.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('691f3542-0597-5ab0-bbe5-14dee88b62ed'::uuid, '7964419c-bdd4-5aae-a544-1ca00a062d7f'::uuid, 'Réalisation — ALT ARCHITECTES', NULL, '["https://lechantier.ma/uploads/media/11b6f4650319.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/11b6f4650319.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('eb8bdf85-f3bb-5719-9d94-73a44b6ac9b7'::uuid, 'f1441635-e806-56f6-a0c1-3ee251a70b17'::uuid, 'Laayoun Appartement', 'Rénovation – Laâyoune Une maison repensée dans un esprit moderne et minimaliste. Lignes épurées, matériaux chaleureux et un rooftop végétalisé avec lounge et piscine pour un art de vivre élégant et connecté à la nature.', '["https://lechantier.ma/uploads/media/804c22719b27.webp", "https://lechantier.ma/uploads/media/653e67a69847.webp", "https://lechantier.ma/uploads/media/f13f1d324077.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/804c22719b27.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('7964eb71-5e64-5944-9872-e2cfbf2c77fb'::uuid, 'f1441635-e806-56f6-a0c1-3ee251a70b17'::uuid, 'Achakkar Gardens', 'Achakar Gardens Un concept résidentiel entre nature et mer, près des Grottes d’Hercule à Tanger. Avec son design minimaliste, ses villas modernes, ses espaces verts, sa piscine et son aire de jeux, Achakar Gardens propose un art de vivre pensé pour le bien-être, la communauté et l’harmonie avec la nature.', '["https://lechantier.ma/uploads/media/cb8ba74be764.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/cb8ba74be764.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('299da765-4deb-5144-9e85-8b1cb2cd68d5'::uuid, 'f1441635-e806-56f6-a0c1-3ee251a70b17'::uuid, 'Réalisation — Chilivin', NULL, '["https://lechantier.ma/uploads/media/653e67a69847.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/653e67a69847.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5e5c8ec2-82c9-553a-a230-4a8e85d68066'::uuid, 'f1441635-e806-56f6-a0c1-3ee251a70b17'::uuid, 'Réalisation — Chilivin', NULL, '["https://lechantier.ma/uploads/media/f13f1d324077.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/f13f1d324077.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2ad2729f-1510-5aa8-933b-3853b7e50598'::uuid, '99335dc4-d7ff-5030-8e64-8aaab69d0f9c'::uuid, 'Villa S', 'Cette villa à Khouribga illustre un style architectural moderne et raffiné, alliant sobriété des lignes et richesse des matériaux. Le projet met en avant une façade rythmée par des volumes géométriques contrastés, créant un équilibre harmonieux entre béton, bois et verre.', '["https://lechantier.ma/uploads/media/74d7212e0236.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/74d7212e0236.webp', 'Khouribga', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('87953ece-6e23-591c-9046-b9c3e9ce1d68'::uuid, '99335dc4-d7ff-5030-8e64-8aaab69d0f9c'::uuid, 'Etablissement scolaire privee', 'Le projet architectural présente une école privée dédiée aux formations professionnelles, pensée comme un espace d’apprentissage moderne, fonctionnel et ouvert sur son environnement urbain.', '["https://lechantier.ma/uploads/media/9d21ae671b46.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/9d21ae671b46.webp', 'Khouribga', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d0f34dcf-9c6d-5f86-b4da-49cdb28ec352'::uuid, '02de04d8-c095-55dd-b58c-ad14d6b67679'::uuid, 'VILLA SG', 'La Villa SG, au cœur de l’Atlas Golf Resort, est un manifeste de simplicité et de contraste. Des volumes clairs, sans emphase, accueillent des matériaux marocains travaillés avec rigueur contemporaine. Ici, tradition et modernité ne s’opposent pas : elles se superposent pour inventer une culture commune.', '["https://lechantier.ma/uploads/media/fb1faa301c82.webp", "https://lechantier.ma/uploads/media/d8a572bfd6f8.webp", "https://lechantier.ma/uploads/media/0caf8f60be99.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/fb1faa301c82.webp', 'Beni Mellal', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9e60547f-b57e-50eb-87eb-952c94279c95'::uuid, '02de04d8-c095-55dd-b58c-ad14d6b67679'::uuid, 'VILLA 1', 'La Villa 1 , A l’Atlas Golf Resort se distingue par une architecture épurée et contemporaine, où la force du volume contraste avec une richesse de détails subtils. Chaque élément, inspiré autant du Maroc que d’ailleurs, vient révéler une élégance unique, créant un lieu moderne, raffiné et profondément accueillant.', '["https://lechantier.ma/uploads/media/0b2aca72ccd8.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/0b2aca72ccd8.webp', 'Beni Mellal', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2d32a341-cb5e-54c1-94b4-d5ef6345e060'::uuid, '02de04d8-c095-55dd-b58c-ad14d6b67679'::uuid, 'Réalisation — mym atelier', NULL, '["https://lechantier.ma/uploads/media/d8a572bfd6f8.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/d8a572bfd6f8.webp', 'Beni Mellal', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
