INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('59635167-e211-5631-b0fa-642f5cb6060b'::uuid, '0560105b-cbbd-5fa2-b0d9-bd8a91ca2f93'::uuid, 'IFMS Rabat', 'L''institut de formation aux métiers de la santé de Rabat (IFMS Rabat) L’agence Archiplan est fière de présenter l’un de ses projets institutionnels majeurs : la conception du nouveau bâtiment de l’IFMS Rabat (Institut de Formation aux Métiers de Santé).', '["https://lechantier.ma/uploads/media/92dd386134ef.webp", "https://lechantier.ma/uploads/media/d720967c9fad.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/92dd386134ef.webp', 'Meknès', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b5891b63-9bc2-5e9d-8528-ac0be2d20c4e'::uuid, '0560105b-cbbd-5fa2-b0d9-bd8a91ca2f93'::uuid, 'Réalisation — Archiplan Architectes Associés', '4, Rue d''Accra', '["https://lechantier.ma/uploads/media/d720967c9fad.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/d720967c9fad.webp', 'Meknès', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('3ad17d20-80ab-5da1-b9e8-5189227df226'::uuid, 'c5038434-450c-5d07-9123-9ba019dba846'::uuid, 'Villa Mirador', 'Villa Mirador est une demeure d’exception, où élégance contemporaine et panorama naturel se rencontrent. Perchée idéalement pour offrir une vue imprenable sur les paysages environnants, la villa séduit par son architecture raffinée, ses lignes épurées et ses matériaux nobles. L’intérieur, baigné de lumière grâce à de larges baies vitrées, combine', '["https://lechantier.ma/uploads/media/0521f6362b2a.webp", "https://lechantier.ma/uploads/media/158aae4e0633.webp", "https://lechantier.ma/uploads/media/b413dda997ab.webp", "https://lechantier.ma/uploads/media/e9403e7064f3.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/0521f6362b2a.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('bfee3086-1785-5779-a7a4-2f0f9eddde5a'::uuid, 'c5038434-450c-5d07-9123-9ba019dba846'::uuid, 'Réalisation — Studio 33 architects', '1 rue madrid et rue hassan 2, immeuble la paternelle, Agadir', '["https://lechantier.ma/uploads/media/158aae4e0633.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/158aae4e0633.webp', 'Agadir', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
