INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('c5f897dd-6dc1-5e03-baff-4e957943dac9'::uuid, '78fcb3ac-fce1-5e81-9358-8c90ce76a779'::uuid, 'Réalisation — Mesos architecture', NULL, '["https://lechantier.ma/uploads/media/3e863cddd974.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3e863cddd974.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('1af14261-cdc3-53f1-a9d4-50388425a14b'::uuid, '6cf6e6ab-71bc-51ed-8d12-f81c80a74112'::uuid, 'Ensemble Résidentiel MORJANA', 'Conception Architecturale et suivi de l’exécution des travaux de construction d’un ensemble résidentiel MORJANA au lotissement Igendis, dans le cadre du nouveau programme d’aide aux logements à la ville de Youssoufia', '["https://lechantier.ma/uploads/media/5add49ed2332.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5add49ed2332.webp', 'Berrechid', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('62c20d4a-de0b-5624-bdbd-36296a783fd9'::uuid, '6cf6e6ab-71bc-51ed-8d12-f81c80a74112'::uuid, 'Centre de Santé Urbain Niveau 1 Demnate', 'Conception Architecturale et suivi des travaux de construction du Centre de Santé Urbain Niveau 1 Demnate, Province d’Azilal.', '["https://lechantier.ma/uploads/media/83cbcb703d93.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/83cbcb703d93.webp', 'Berrechid', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a9160917-a904-57cf-b1f5-bfe141578085'::uuid, '8cf80d71-345c-5436-bc71-89b7d61d2b31'::uuid, 'Lotissement Villa Marrakech', 'Résidence de haut standing composée de 20 villas à Marrakech. Une architecture contemporaine qui conjugue transparence des espaces de vie et volumes protecteurs à l’étage. Le contraste entre légèreté et massivité crée une esthétique élégante, au service du confort et de l’intimité.', '["https://lechantier.ma/uploads/media/583549fbefe0.webp", "https://lechantier.ma/uploads/media/849298a2cdf6.webp", "https://lechantier.ma/uploads/media/28c0c5b26398.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/583549fbefe0.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e3aea203-bc51-59ca-b2ee-ae7a5b20e17a'::uuid, '8cf80d71-345c-5436-bc71-89b7d61d2b31'::uuid, 'Villa Ahlam - Bahia Golf Beach', 'Conçue autour du principe de transparence, la villa Ahlam efface les frontières entre intérieur et extérieur. Le rez-de-chaussée s’ouvre généreusement sur le jardin, prolongeant les espaces de vie et amplifiant la perception de l’espace. À l’étage, un volume dense préserve l’intimité des chambres tout en affirmant l’ancrage du bâti.', '["https://lechantier.ma/uploads/media/6a7f0fef1e34.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/6a7f0fef1e34.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d11930cb-eb1c-59a3-aa2e-8d4acf79f1e3'::uuid, '8cf80d71-345c-5436-bc71-89b7d61d2b31'::uuid, 'Réalisation — RS ARCHI', NULL, '["https://lechantier.ma/uploads/media/849298a2cdf6.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/849298a2cdf6.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9868e2b8-db3a-59d8-83f4-8dd60646b649'::uuid, '8cf80d71-345c-5436-bc71-89b7d61d2b31'::uuid, 'Réalisation — RS ARCHI', NULL, '["https://lechantier.ma/uploads/media/28c0c5b26398.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/28c0c5b26398.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('59043f36-9bc7-5ea3-9181-7bc47e8d2bd9'::uuid, '3076598e-1618-5e93-b2e4-3be8df0baac5'::uuid, 'Villa BA', 'La Villa BA se distingue par son architecture minimaliste et l’usage du béton brut en façade, offrant un rendu sobre et élégant. Les grandes ouvertures verticales et horizontales apportent une lumière naturelle abondante, créant un dialogue harmonieux entre intérieur et extérieur.', '["https://lechantier.ma/uploads/media/bec19c493724.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/bec19c493724.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('4011097e-5868-5a76-8986-1fa812bca7fb'::uuid, '3076598e-1618-5e93-b2e4-3be8df0baac5'::uuid, 'IMMEUBLE', 'IMMEUBLE RESIDENTIEL EN R+6', '[]'::jsonb, NULL, 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('485e29e2-6fde-5eef-8217-894c8a042f6c'::uuid, 'b4ba2f5d-9877-5d61-999a-67407508bf1e'::uuid, 'Studio O', 'Cette rénovation réinvente un studio compact au cœur de Guéliz à travers une palette restreinte mais affirmée : couleurs vibrantes, matériaux tactiles et lignes épurées. Le projet explore la continuité spatiale et la clarté fonctionnelle, où chaque choix — du mobilier à la teinte des murs — contribue à redéfinir l’expérience de l’habiter.', '["https://lechantier.ma/uploads/media/55d2a94ec769.webp", "https://lechantier.ma/uploads/media/dbfd5d80643b.webp", "https://lechantier.ma/uploads/media/23d305c1cd8e.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/55d2a94ec769.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('1b5f1cc1-ec1f-570f-8a87-67bfc7aadf0f'::uuid, 'b4ba2f5d-9877-5d61-999a-67407508bf1e'::uuid, 'Villa SM', 'Villa SM Le projet Villa SM s’inscrit dans une démarche de synthèse entre ancrage local et exigences contemporaines. Développée autour d’un volume simple et maîtrisé, l’architecture met en valeur la matérialité du lieu tout en offrant à chaque espace intérieur une ouverture fluide vers l’extérieur.', '["https://lechantier.ma/uploads/media/9237816bcf6b.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/9237816bcf6b.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('7ac3a15d-9ea0-523e-a370-3fc002aa95aa'::uuid, 'b4ba2f5d-9877-5d61-999a-67407508bf1e'::uuid, 'Réalisation — GENESIS SYSTEMS ARCHITECTURE', NULL, '["https://lechantier.ma/uploads/media/dbfd5d80643b.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/dbfd5d80643b.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
