INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('81f1c745-27f8-5dae-bfb2-4c6c8846ed57'::uuid, 'cec1eb15-a8d2-5b37-8e98-7a08a08f58e6'::uuid, '🏢 Immeuble d''habitation – Client privé', 'Pensé pour un cadre de vie confortable et fonctionnel, l’immeuble s’insère harmonieusement dans le tissu urbain tout en affirmant une identité élégante et actuelle, parfaitement adaptée au climat et à l’esthétique locale.', '["https://lechantier.ma/uploads/media/877f7a4a96c1.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/877f7a4a96c1.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
