INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('1201c1aa-14b9-579a-b846-98c8d45aa3c2'::uuid, 'ea7ab025-fb55-59ba-b26a-f52a2b561053'::uuid, 'CONSTRUCTION D''UN IMMEUBLE EN R+5', 'Immeuble R+5 à usage résidentiel, incluant un rez-de-chaussée habité. Appartements bien distribués sur 6 niveaux, avec ascenseur, escaliers, ventilation naturelle et conformité aux normes techniques et de sécurité.', '["https://lechantier.ma/uploads/media/dead4a6e836e.webp", "https://lechantier.ma/uploads/media/3a846521d384.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/dead4a6e836e.webp', 'Skhirat', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('8346b33a-c46c-59a7-b312-9e8f55ef91b9'::uuid, 'ea7ab025-fb55-59ba-b26a-f52a2b561053'::uuid, 'CONSTRUCTION D''UNE VILLA EN R+1 AVEC S/S', 'Villa moderne en R+1 avec sous-sol, composée d’un salon spacieux, cuisine ouverte, suite parentale au rez-de-chaussée, chambres à l’étage avec balcons, et sous-sol aménagé en garage, buanderie ou espace de loisirs. Design lumineux, fonctionnel et confortable.', '["https://lechantier.ma/uploads/media/5560f2894220.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5560f2894220.webp', 'Skhirat', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
