INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('03dbf8c8-bbf4-5157-8898-414982cc089a'::uuid, '95d26b67-accb-554c-b610-bd257223cf1a'::uuid, 'Résidence de villas à Marrakech', 'DOMAINE MAJORELLE - Résidence fermée de villas haut de gamme à Marrakech, pensée autour de trois typologies : villas jumelées, villas en bande et villas isolées. Une architecture aux inspirations marocaines contemporaines, mêlant matières minérales, jeux de lumière et végétation désertique pour créer un cadre de vie élégant, intime et apaisant.', '["https://lechantier.ma/uploads/media/a510b7794cfe.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/a510b7794cfe.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('ee2b1a44-7a5c-5202-8c40-fd3e7f55b011'::uuid, '95d26b67-accb-554c-b610-bd257223cf1a'::uuid, 'Construction Villa contemporaine', 'VILLA Y - Villa contemporaine inspirée du style brésilien, mêlant lignes horizontales, béton brut et bois chaleureux. Les espaces s’ouvrent largement sur l’extérieur, en dialogue direct avec une végétation luxuriante et une piscine miroir, pour une atmosphère à la fois élégante, apaisante et résolument haut de gamme.', '[]'::jsonb, NULL, 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
