INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('0c1cbcee-1f66-5604-a4a9-1df7e8236c9c'::uuid, 'e63fe3db-a885-5b57-a1d6-21bfd6099d46'::uuid, 'Coverage areas', 'CasablancaFèsRabat', '[]'::jsonb, NULL, 'Fès', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2d344fab-891d-5519-849c-f0704ffa04af'::uuid, '1dac0dae-3fb4-52d3-8f4e-778027ee5eef'::uuid, 'La Croissanterie- Tanger', 'La Croissanterie fait rimer luxe avec optimisation de l''espace. Ce café intime s''agrandit visuellement grâce à des pavés de verre émeraude, des miroirs arqués et des tables suspendues. Son minimalisme haptique mêlant microciment, velours sauge et lumière chaude offre une expérience haut de gamme et ingénieuse.', '["https://lechantier.ma/uploads/media/5a90e8e6bace.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5a90e8e6bace.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('681c993a-063a-5068-99cc-c8c59bf03caa'::uuid, '1dac0dae-3fb4-52d3-8f4e-778027ee5eef'::uuid, 'Villa Intima - Cabo Negro', 'À Cabo Negro, la Villa Intima célèbre l''art de vivre méditerranéen par son architecture duelle. Sa façade sur rue préserve l''intimité, tandis que l''arrière s''ouvre sur le paysage par de vastes arches. L''intérieur , alliant tadelakt, zellige et lumière, elle incarne un luxe organique et apaisant.', '[]'::jsonb, NULL, 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
