INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('38fee43b-95af-5942-95f8-4d43487680ec'::uuid, '174fffeb-bc51-5e32-ae5f-bc7ff1e11b9c'::uuid, 'INDRIVE', 'INDRIVE Ce plateau de bureaux a été conçu comme un espace de travail contemporain, dynamique et collaboratif, en cohérence avec l’identité innovante de inDrive. L’aménagement privilégie une organisation fluide des espaces, alternant zones de travail ouvertes, salles de réunion vitrées et espaces informels favorisant l’échange et la créativité. Le', '["https://lechantier.ma/uploads/media/b45adb845415.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/b45adb845415.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('35334dd9-073d-5e56-ae30-61efaf76106d'::uuid, '174fffeb-bc51-5e32-ae5f-bc7ff1e11b9c'::uuid, 'Restaurant', 'CHEEZY BOX L’aménagement de ce restaurant a été pensé comme une expérience immersive, où l’architecture intérieure participe pleinement à l’identité du lieu et à son atmosphère nocturne. Le projet s’appuie sur une palette de matériaux bruts et contemporains — textures minérales, surfaces sombres et touches métalliques — renforcée par un travail s', '[]'::jsonb, NULL, 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
